#!/usr/bin/env python3
"""
Applies the sequential-round-predictability fix (Fix #3): a round can only be
predicted once every EARLIER round in the same season has left `open` — the
new `isRoundPredictable` domain rule, enforced in `SubmitPrediction` and
surfaced on the wire as `RoundDto.isPredictable` (schema v2), consumed by the
mobile rounds/fixtures/prediction screens.

Run from the repo root (~/nukhbaa):
    python3 apply_round_sequencing.py

Each MODIFIED file is patched via a single whole-file replace hunk (old =
this script's recorded original content, new = the fully-patched content).
Before touching a file, it is compared to its already-patched target content
-- if it already matches, the file is skipped untouched (safe to re-run).
If a file's current content matches neither the expected original NOR the
target, the script stops immediately with an explicit error naming the file,
and nothing further is written. NEW files are created only if they do not
already exist (if one exists with different content, the script stops rather
than overwrite it silently).
"""
from __future__ import annotations
import base64, sys
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent


def fail(message: str) -> None:
    print(f"ERROR: {message}", file=sys.stderr)
    sys.exit(1)


# Each entry: (path, original_b64, target_b64). The whole file is replaced in
# one shot -- this is a single, exact, all-or-nothing hunk per file.
PATCHES: list[tuple[str, str, str]] = [
    ('packages/domain/lib/domain.dart', '', ''),
    ('packages/application/lib/src/prediction/submit_prediction.dart', '', ''),
    ('packages/application/test/prediction/submit_prediction_test.dart', '', ''),
    ('packages/contracts/lib/src/competition_dto.dart', '', ''),
    ('packages/contracts/test/competition_dto_test.dart', '', ''),
    ('apps/server/lib/http/competition_dto_mapper.dart', '', ''),
    ('apps/server/routes/seasons/[id]/rounds/index.dart', '', ''),
    ('apps/server/routes/rounds/[id]/index.dart', '', ''),
    ('apps/server/routes/rounds/[id]/lock/index.dart', '', ''),
    ('apps/server/test/routes/season_rounds_test.dart', '', ''),
    ('apps/server/test/routes/rounds_browse_test.dart', '', ''),
    ('apps/server/test/routes/seasons_rounds_browse_test.dart', '', ''),
    ('apps/mobile/lib/features/competition/round_fixtures_screen.dart', '', ''),
    ('apps/mobile/lib/features/competition/season_rounds_screen.dart', '', ''),
    ('apps/mobile/lib/features/prediction/prediction_screen.dart', '', ''),
    ('apps/mobile/lib/core/error/error_presenter.dart', '', ''),
    ('apps/mobile/lib/l10n/app_en.arb', '', ''),
    ('apps/mobile/lib/l10n/app_ar.arb', '', ''),
    ('apps/mobile/lib/l10n/app_localizations.dart', '', ''),
    ('apps/mobile/lib/l10n/app_localizations_en.dart', '', ''),
    ('apps/mobile/lib/l10n/app_localizations_ar.dart', '', ''),
    ('apps/mobile/test/support/prediction_harness.dart', '', ''),
    ('apps/mobile/test/features/prediction/prediction_screen_test.dart', '', ''),
]

# Each entry: (path, content_b64). Created only if absent.
NEW_FILES: list[tuple[str, str]] = [
    ('packages/domain/lib/src/competition/round_sequencing.dart', ''),
    ('packages/domain/test/competition/round_sequencing_test.dart', ''),
    ('apps/server/test/routes/round_lock_test.dart', ''),
]


def apply_patches() -> None:
    for rel_path, orig_b64, target_b64 in PATCHES:
        path = REPO_ROOT / rel_path
        if not path.exists():
            fail(f"File not found: {rel_path}")

        text = path.read_text(encoding="utf-8")
        target = base64.b64decode(target_b64).decode("utf-8")

        if text == target:
            print(f"= {rel_path} (already applied, skipping)")
            continue

        original = base64.b64decode(orig_b64).decode("utf-8")
        if text != original:
            fail(
                f"{rel_path}: current content matches neither the expected "
                "original nor the already-patched target. The file changed "
                "since this script was generated (or was already partially "
                "hand-edited). Refusing to overwrite blindly."
            )

        path.write_text(target, encoding="utf-8")
        print(f"\u2713 patched {rel_path}")


def create_new_files() -> None:
    for rel_path, content_b64 in NEW_FILES:
        path = REPO_ROOT / rel_path
        content = base64.b64decode(content_b64).decode("utf-8")

        if path.exists():
            existing = path.read_text(encoding="utf-8")
            if existing == content:
                print(f"= {rel_path} (already exists, identical, skipping)")
                continue
            fail(
                f"{rel_path}: already exists with DIFFERENT content. "
                "Refusing to overwrite -- inspect it by hand."
            )

        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
        print(f"\u2713 created {rel_path}")


def main() -> None:
    print("Applying the sequential-round-predictability fix (Fix #3)...\n")
    apply_patches()
    create_new_files()
    print(
        "\nDone. Next steps:\n"
        "  cd ~/nukhbaa\n"
        "  melos bootstrap   # or: (cd packages/domain && flutter pub get) etc.\n"
        "  # Package tests (no Flutter widget runner needed for these three):\n"
        "  cd packages/domain && dart test test/competition/round_sequencing_test.dart\n"
        "  cd ../application && dart test test/prediction/submit_prediction_test.dart\n"
        "  cd ../contracts && dart test test/competition_dto_test.dart\n"
        "  # Server route tests:\n"
        "  cd ../../apps/server && dart test test/routes/season_rounds_test.dart "
        "test/routes/rounds_browse_test.dart test/routes/seasons_rounds_browse_test.dart "
        "test/routes/round_lock_test.dart\n"
        "  # Mobile (needs the full Flutter env -- proot Ubuntu):\n"
        "  cd ../../apps/mobile && flutter test "
        "test/features/prediction/prediction_screen_test.dart\n"
    )


if __name__ == '__main__':
    main()
